import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC10%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%BF%9B%E5%BA%A6%E7%AE%A1%E7%90%86/10.1%20%E8%BF%9B%E5%BA%A6%E8%AE%A1%E5%88%92.html","title":"10.1 进度计划","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第10章 项目进度管理/10.1 进度计划.md"}`),a={name:`10.1 进度计划.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_10-1-进度计划" tabindex="-1"><a class="header-anchor" href="#_10-1-进度计划"><span>10.1 进度计划</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>进度计划是指确定项目活动的顺序、持续时间和资源需求，并制定项目时间表的过程。</p><h2 id="进度计划编制步骤" tabindex="-1"><a class="header-anchor" href="#进度计划编制步骤"><span>进度计划编制步骤</span></a></h2><h3 id="_1-活动定义" tabindex="-1"><a class="header-anchor" href="#_1-活动定义"><span>1. 活动定义</span></a></h3><ul><li><strong>任务</strong>：识别项目所需的具体活动</li><li><strong>输出</strong>：活动清单</li><li><strong>方法</strong>：分解技术、滚动式规划</li></ul><h3 id="_2-活动排序" tabindex="-1"><a class="header-anchor" href="#_2-活动排序"><span>2. 活动排序</span></a></h3><ul><li><strong>任务</strong>：确定活动之间的依赖关系</li><li><strong>输出</strong>：项目进度网络图</li><li><strong>方法</strong>：前导图法（PDM）、箭线图法（ADM）</li></ul><h3 id="_3-活动历时估算" tabindex="-1"><a class="header-anchor" href="#_3-活动历时估算"><span>3. 活动历时估算</span></a></h3><ul><li><strong>任务</strong>：估算每个活动的持续时间</li><li><strong>输出</strong>：活动历时估算结果</li><li><strong>方法</strong>：专家判断、类比估算、参数估算、三点估算</li></ul><h3 id="_4-进度计划编制" tabindex="-1"><a class="header-anchor" href="#_4-进度计划编制"><span>4. 进度计划编制</span></a></h3><ul><li><strong>任务</strong>：整合活动顺序和历时估算，制定进度计划</li><li><strong>输出</strong>：项目进度计划、进度基准</li><li><strong>方法</strong>：关键路径法、资源平衡</li></ul><h2 id="活动历时估算方法" tabindex="-1"><a class="header-anchor" href="#活动历时估算方法"><span>活动历时估算方法</span></a></h2><h3 id="_1-专家判断" tabindex="-1"><a class="header-anchor" href="#_1-专家判断"><span>1. 专家判断</span></a></h3><ul><li><strong>特点</strong>：基于专家经验</li><li><strong>适用</strong>：缺乏历史数据的项目</li></ul><h3 id="_2-类比估算" tabindex="-1"><a class="header-anchor" href="#_2-类比估算"><span>2. 类比估算</span></a></h3><ul><li><strong>特点</strong>：基于类似项目的经验</li><li><strong>适用</strong>：早期阶段或类似项目</li></ul><h3 id="_3-参数估算" tabindex="-1"><a class="header-anchor" href="#_3-参数估算"><span>3. 参数估算</span></a></h3><ul><li><strong>特点</strong>：基于数学模型</li><li><strong>适用</strong>：有大量历史数据的项目</li></ul><h3 id="_4-三点估算" tabindex="-1"><a class="header-anchor" href="#_4-三点估算"><span>4. 三点估算</span></a></h3><ul><li><strong>公式</strong>：(乐观时间 + 4×最可能时间 + 悲观时间) / 6</li><li><strong>特点</strong>：考虑不确定性</li></ul><h2 id="进度计划的表示方法" tabindex="-1"><a class="header-anchor" href="#进度计划的表示方法"><span>进度计划的表示方法</span></a></h2><h3 id="_1-甘特图" tabindex="-1"><a class="header-anchor" href="#_1-甘特图"><span>1. 甘特图</span></a></h3><ul><li><strong>特点</strong>：直观展示活动进度</li><li><strong>适用</strong>：项目进度监控</li></ul><h3 id="_2-项目进度网络图" tabindex="-1"><a class="header-anchor" href="#_2-项目进度网络图"><span>2. 项目进度网络图</span></a></h3><ul><li><strong>特点</strong>：展示活动之间的依赖关系</li><li><strong>适用</strong>：复杂项目的进度分析</li></ul><h3 id="_3-里程碑图" tabindex="-1"><a class="header-anchor" href="#_3-里程碑图"><span>3. 里程碑图</span></a></h3><ul><li><strong>特点</strong>：突出关键里程碑</li><li><strong>适用</strong>：高层汇报</li></ul><h2 id="进度计划的类型" tabindex="-1"><a class="header-anchor" href="#进度计划的类型"><span>进度计划的类型</span></a></h2><h3 id="_1-主进度计划" tabindex="-1"><a class="header-anchor" href="#_1-主进度计划"><span>1. 主进度计划</span></a></h3><ul><li><strong>内容</strong>：主要里程碑和关键活动</li><li><strong>适用</strong>：项目整体进度控制</li></ul><h3 id="_2-详细进度计划" tabindex="-1"><a class="header-anchor" href="#_2-详细进度计划"><span>2. 详细进度计划</span></a></h3><ul><li><strong>内容</strong>：所有活动的详细安排</li><li><strong>适用</strong>：项目执行和监控</li></ul><h3 id="_3-滚动式计划" tabindex="-1"><a class="header-anchor" href="#_3-滚动式计划"><span>3. 滚动式计划</span></a></h3><ul><li><strong>特点</strong>：近期详细、远期粗略</li><li><strong>适用</strong>：需求不确定的项目</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>进度计划编制步骤</strong></li><li><strong>活动历时估算方法</strong></li><li><strong>进度计划的表示方法</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>定义排序估算编制，进度计划四步骤，估算方法要选对</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪种活动历时估算方法考虑了不确定性？ A. 专家判断 B. 类比估算 C. 参数估算 D. 三点估算</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>：三点估算考虑了乐观时间、最可能时间和悲观时间，通过加权平均计算，考虑了活动历时的不确定性。</p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};